-- =====================================================================
-- Item API: seed data  (run SECOND, after schema.sql)
-- 6 categories and the 89 items that used to be the hardcoded list in index.py.
-- Original ids 1-89 are kept so the three websites keep working.
-- =====================================================================



-- Identity columns do not advance when ids are inserted explicitly:
-- move the counter past 89 so the next POST gets id 90.
select setval(pg_get_serial_sequence('public.items', 'id'), (select max(id) from public.items));